package com.trevasq.qguard.api;
import com.trevasq.qguard.api.ApiDtos.ErrorResponse; import com.trevasq.qguard.service.*; import org.springframework.http.*; import org.springframework.web.bind.*; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(SchedulingService.SlotTakenException.class) @ResponseStatus(HttpStatus.CONFLICT) ErrorResponse conflict(){return new ErrorResponse("SLOT_UNAVAILABLE","That slot is no longer available.");} @ExceptionHandler(BookingService.UnknownManagementTokenException.class) @ResponseStatus(HttpStatus.NOT_FOUND) ErrorResponse absent(){return new ErrorResponse("NOT_FOUND","Booking not found.");} @ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class}) @ResponseStatus(HttpStatus.BAD_REQUEST) ErrorResponse invalid(Exception e){return new ErrorResponse("VALIDATION_ERROR",e instanceof IllegalArgumentException?e.getMessage():"Invalid request.");} }
